          <div className="flex min-h-60 flex-col rounded-xl border border-border/70 bg-muted/20 p-2">
            {!activePath ? (
              <div className="flex flex-1 items-center justify-center p-6 text-center text-[10px] text-muted-foreground">
                点击左侧文件开始编辑
              </div>
