                  spellCheck={false}
                  className="min-h-48 flex-1 resize-y rounded-lg border border-border/60 bg-card p-2.5 font-mono text-xs leading-relaxed text-foreground focus:border-primary/50 focus:outline-none md:min-h-[38dvh]"
