              placeholder={isGit ? "https://github.com/org/my-skill.git" : "/path/to/skill（须包含 SKILL.md）"}
              className="h-9 rounded-xl border-border bg-muted/40 font-mono text-xs focus:border-primary/50 focus:ring-primary/20"
            />
